mapper.select:
select m.*, m2.membershipNo, m2.expirationDate, m2.status from fitian.`Member` m left join fitian.Membership m2 on m.uid = m2.uid where m.boxCode = #{boxCode} AND (m2.status IS NULL OR m2.status <> 'DELETE') and m.useYN = 'Y'
AND (m.rank = 'manager' OR m.rank = 'owner')
AND m.rank = #{rank}

mapper.update:
update fitian.Member
name = #{name}, email = #{email}, useYN = 'Y'
where uid = #{uid}
